<?php
namespace Tests\Feature;
use Symfony\Component\Process\Process;use Tests\TestCase;
class Milestone3gzProfileUpdateRequestAuthorizationContractTest extends TestCase{
 private const BASE='dab66744bf820b3b7ae525fb475828485790e29a';private const SUBJECT='Approve profile update request contract';private const FILES=['backend/docs/milestone_3gz_profile_update_request_authorization_contract.md','backend/tests/Feature/Milestone3gzProfileUpdateRequestAuthorizationContractTest.php'];
 public function test_exact_contract_decisions():void{$d=file_get_contents(__DIR__.'/../../docs/milestone_3gz_profile_update_request_authorization_contract.md');foreach([self::BASE,'contract-only','`profile_updates.self.submit`','`profile_updates.self.view`','`profile_updates.review`','`profile_updates.approve`','Treasurer | Yes | Yes | No | No','Normal Member | Yes | Yes | No | No','`email`','One Pending request','1-20 entries','201','submitted_at desc, id desc','defaults to 25','capped at 100','never restricted values','lock version','stale Member','409','no DELETE route','profile_update_requests','profile_update_request_changes','profile_updates.stale_conflict','GO - 3HA'] as $x)$this->assertStringContainsStringIgnoringCase($x,$d);}
 public function test_contract_retains_scope_allowlist():void{$s=file_get_contents(__DIR__.'/../../docs/milestone_3gy_profile_update_request_scope_gate.md');$d=file_get_contents(__DIR__.'/../../docs/milestone_3gz_profile_update_request_authorization_contract.md');foreach(['full_name','birth_date','occupation','phone','address_line_1','blood_group','blood_donor_consent'] as $x){$this->assertStringContainsString($x,$s);$this->assertStringContainsString($x,$d);}}
 public function test_changed_file_scope_is_lifecycle_safe():void{$r=dirname(__DIR__,3);$c=$this->find($r);if(!$c){$this->assertSame(self::BASE,trim($this->git($r,['rev-parse','HEAD'])));$l=array_values(array_filter(explode("\n",rtrim($this->git($r,['status','--porcelain=v1','-uall']),"\r\n"))));$f=array_map(fn($x)=>str_replace('\\','/',substr($x,3)),$l);}else{$f=$this->lines($r,['diff-tree','--no-commit-id','--name-only','-r',$c]);}$e=self::FILES;sort($f);sort($e);$this->assertSame($e,$f);}private function find($r):?string{$m=[];foreach($this->lines($r,['log','--all','--format=%H%x09%s']) as $l){[$h,$s]=array_pad(explode("\t",$l,2),2,'');if($s===self::SUBJECT)$m[]=$h;}$this->assertLessThanOrEqual(1,count($m));return $m[0]??null;}private function lines($r,$a):array{return array_values(array_filter(explode("\n",trim($this->git($r,$a)))));}private function git($r,$a):string{$p=new Process(['git',...$a],$r);$p->setTimeout(30);$p->run();$this->assertTrue($p->isSuccessful(),$p->getErrorOutput());return str_replace("\r\n","\n",$p->getOutput());}}
